}

/**
 * @brief AABBTree::isDegeneratedTriangle
 * @param t
 * @return
 */
CG3_INLINE bool AABBTree3::isDegeneratedTriangle(const AABBTree3::CGALTriangle& t)
{
    return (t[0] == t[1] || t[0] == t[2] || t[1] == t[2]);
}

